css:
.container {
  width: 100%;
  height: 100%;
  /* Add your background pattern here */
  background-image: radial-gradient(
      circle at 52% 48%,
      #ffebf5 10%,
      transparent 15%
    ),
    radial-gradient(circle at 50% 50%, #ffbcdd 20%, transparent 20%),
    radial-gradient(circle at 40% 40%, #ff0080 20%, transparent 21%),
    radial-gradient(circle at 60% 60%, #ff1288 20%, transparent 21%),
    radial-gradient(circle at 60% 40%, #ff2c96 20%, transparent 21%),
    radial-gradient(circle at 40% 60%, #ff44a1 20%, transparent 21%);
  background-size: 100px 100px;
  background-position: center;
}
